import{g as a,E as r,o as s,c as d,l as t,b as l,H as i,ao as n}from"./chunks/framework.C_cxhC_b.js";const c="/video/feishu20261108-182724.mp4",_=JSON.parse('{"title":"「群蜂重建」：让 18 个 AI 光标把首页重新造一遍","description":"复刻 swarm-rebuild 的「群蜂重建」：18 个自主设计光标用边界框、W×H 实时测量、打字机和程序化 Web Audio，把整个首页逐个元素重新建造一遍。含完整提示词拆解、分镜、实现架构与踩坑记录。","frontmatter":{"title":"「群蜂重建」：让 18 个 AI 光标把首页重新造一遍","date":"2026-11-08T00:00:00.000Z","updated":"2026-11-08T00:00:00.000Z","lastUpdated":"2026-11-08T04:00:00.000Z","progress":100,"description":"复刻 swarm-rebuild 的「群蜂重建」：18 个自主设计光标用边界框、W×H 实时测量、打字机和程序化 Web Audio，把整个首页逐个元素重新建造一遍。含完整提示词拆解、分镜、实现架构与踩坑记录。","tags":["AI","动画","Vue.js"]},"headers":[],"relativePath":"ai/swarm-rebuild.md","filePath":"ai/swarm-rebuild.md","lastUpdated":1794110400000}'),p={name:"ai/swarm-rebuild.md"};function h(u,o,m,g,k,b){const e=r("NolebasePageProperties");return s(),d("div",null,[o[0]||(o[0]=t("h1",{id:"「群蜂重建」-让-18-个-ai-光标把首页重新造一遍",tabindex:"-1"},[l("「群蜂重建」：让 18 个 AI 光标把首页重新造一遍 "),t("a",{class:"header-anchor",href:"#「群蜂重建」-让-18-个-ai-光标把首页重新造一遍","aria-label":'Permalink to "「群蜂重建」：让 18 个 AI 光标把首页重新造一遍"'},"​")],-1)),i(e),o[1]||(o[1]=t("p",null,"首页视频播完，页面被擦成一块画布。一群彩色设计光标飞进来，拉框、量尺寸、打字、复制，把整页重新「施工」出来——最后交还给真实的页面。",-1)),o[2]||(o[2]=t("p",null,[t("video",{src:c,controls:"",playsinline:"",preload:"metadata"})],-1)),o[3]||(o[3]=n('<blockquote><p>这套东西不是画的假图，而是<strong>真的对着当前页面的 DOM 扫一遍，再按元素逐个重画</strong>。下面从提示词、最终效果、实现细节三部分完整记录一遍。</p></blockquote><h2 id="一、需求提示词" tabindex="-1">一、需求提示词 <a class="header-anchor" href="#一、需求提示词" aria-label="Permalink to &quot;一、需求提示词&quot;">​</a></h2><p>原始诉求（保留了当时的措辞）：</p><div class="rp-prompt" style="--rp-prompt-accent:#6366F1;"><div class="rp-prompt__backdrop"></div><div class="rp-prompt__panel"><div class="rp-prompt__header"><div class="rp-prompt__meta"><span class="rp-prompt__eyebrow"><span class="rp-prompt__icon" title="Codex"><svg aria-hidden="true" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M19.503 0H4.496A4.496 4.496 0 000 4.496v15.007A4.496 4.496 0 004.496 24h15.007A4.496 4.496 0 0024 19.503V4.496A4.496 4.496 0 0019.503 0z" fill="#fff"></path><path d="M9.064 3.344a4.578 4.578 0 012.285-.312c1 .115 1.891.54 2.673 1.275.01.01.024.017.037.021a.09.09 0 00.043 0 4.55 4.55 0 013.046.275l.047.022.116.057a4.581 4.581 0 012.188 2.399c.209.51.313 1.041.315 1.595a4.24 4.24 0 01-.134 1.223.123.123 0 00.03.115c.594.607.988 1.33 1.183 2.17.289 1.425-.007 2.71-.887 3.854l-.136.166a4.548 4.548 0 01-2.201 1.388.123.123 0 00-.081.076c-.191.551-.383 1.023-.74 1.494-.9 1.187-2.222 1.846-3.711 1.838-1.187-.006-2.239-.44-3.157-1.302a.107.107 0 00-.105-.024c-.388.125-.78.143-1.204.138a4.441 4.441 0 01-1.945-.466 4.544 4.544 0 01-1.61-1.335c-.152-.202-.303-.392-.414-.617a5.81 5.81 0 01-.37-.961 4.582 4.582 0 01-.014-2.298.124.124 0 00.006-.056.085.085 0 00-.027-.048 4.467 4.467 0 01-1.034-1.651 3.896 3.896 0 01-.251-1.192 5.189 5.189 0 01.141-1.6c.337-1.112.982-1.985 1.933-2.618.212-.141.413-.251.601-.33.215-.089.43-.164.646-.227a.098.098 0 00.065-.066 4.51 4.51 0 01.829-1.615 4.535 4.535 0 011.837-1.388zm3.482 10.565a.637.637 0 000 1.272h3.636a.637.637 0 100-1.272h-3.636zM8.462 9.23a.637.637 0 00-1.106.631l1.272 2.224-1.266 2.136a.636.636 0 101.095.649l1.454-2.455a.636.636 0 00.005-.64L8.462 9.23z" fill="#6366F1"></path></svg></span>For your Agent</span></div><div class="rp-prompt__header-row"><div class="rp-prompt__header-left"><div class="rp-prompt__title-with-icon"><div class="rp-prompt__title">一键创建项目</div></div><p class="rp-prompt__description">复制后发给 Agent</p></div><div class="rp-prompt__header-actions"><button type="button" class="rp-prompt__action-copy" title="复制 Prompt"><svg class="rp-prompt__action-icon" xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24"><path fill="currentColor" d="M20 8v12H8V8zm0-2H8a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2"></path><path fill="currentColor" d="M4 16H2V4a2 2 0 0 1 2-2h12v2H4Z"></path></svg><span>复制 Prompt</span></button><button type="button" class="rp-prompt__action-toggle" aria-controls="rp-prompt-content-1" aria-expanded="false" title="展开"><svg class="rp-prompt__action-toggle-icon" width="1em" height="1em" viewBox="0 0 32 32"><path fill="currentColor" d="M16 22 6 12l1.4-1.4 8.6 8.6 8.6-8.6L26 12z"></path></svg></button></div></div></div><div id="rp-prompt-content-1" class="rp-prompt__content rp-prompt__content--collapsed" aria-hidden="true"><div class="rp-prompt__content-inner"><div class="rp-prompt__content-body" style="white-space:pre-wrap;">按照官方指南创建项目。 学习这个项目 `https://github.com/JoelBastoneLopez/swarm-rebuild`，他就能完美实现我的首页效果，并指挥一群自主的设计光标，使用边界框、实时测量、打字机字体和程序化声音，逐个元素地重建网页。</div></div></div></div></div><p>一句话里有四个硬指标：<strong>自主光标群</strong>、<strong>边界框 + 实时测量</strong>、<strong>打字机字体</strong>、<strong>程序化声音</strong>，落点是「逐个元素重建网页」。</p><hr><h2 id="二、把一句话拆成可执行的提示词" tabindex="-1">二、把一句话拆成可执行的提示词 <a class="header-anchor" href="#二、把一句话拆成可执行的提示词" aria-label="Permalink to &quot;二、把一句话拆成可执行的提示词&quot;">​</a></h2><p>真正写代码前，先把它拆成八条可以验收的约束（相当于给自己写的系统提示词）：</p><ol><li><strong>接管整页</strong>：覆盖层瞬间铺满，底色从页面真实背景取色；视口套一圈深色细边框，页面内容隐藏但不销毁。</li><li><strong>光标要像人</strong>：28×28 多形态（箭头 / 复制 / 十字 / I 形），带真实热点、按压缩放、随移动方向转向；不是一张静态 PNG。</li><li><strong>扫描真实 DOM</strong>：遍历页面元素建节点树，按「同父级、同长相」找可复用组；产出条目上限兜底，隐藏元素跳过。</li><li><strong>建造语法是 Figma 的</strong>：十字光标拉框 → 右下角 <code>W × H</code> 徽章实时跳动 → 灰色占位 → 交叉淡入真身 → 文字用 I 形光标逐字打出。</li><li><strong>同构块复制</strong>：母块建完才允许复制；复制要「块内抓取 → 1:1 跟手拖动 → 两红框 + 间距读数 → 弹性落位 → 选中框停留」。</li><li><strong>声音全部程序化</strong>：Web Audio 现场合成振荡器、噪声、泛音，不加载任何 MP3。</li><li><strong>镜头自己游览</strong>：施工前沿走到哪，镜头跟到哪；收工后精确交接，不能出现两份页脚叠在一起。</li><li><strong>可中断、可重播、可降级</strong>：Esc 随时退出；「开始」每次重播；<code>prefers-reduced-motion</code> 直接退回原来的下滑一屏。</li></ol><hr><h2 id="三、最终效果-分镜" tabindex="-1">三、最终效果（分镜） <a class="header-anchor" href="#三、最终效果-分镜" aria-label="Permalink to &quot;三、最终效果（分镜）&quot;">​</a></h2><h3 id="分镜一-开场-·-扫描中" tabindex="-1">分镜一：开场 · 扫描中 <a class="header-anchor" href="#分镜一-开场-·-扫描中" aria-label="Permalink to &quot;分镜一：开场 · 扫描中&quot;">​</a></h3><ul><li>画布铺满，颜色取自当前主题背景，四周一圈深色内描边。</li><li>中央浮着一个小立方体，HUD 左侧显示「扫描中…」。</li><li><strong>18 个光标</strong>从屏幕两侧飞入，围着立方体聚成一个圈；HUD 左下角最多露 6 个色点，代表在场光标。</li></ul><h3 id="分镜二-开工" tabindex="-1">分镜二：开工 <a class="header-anchor" href="#分镜二-开工" aria-label="Permalink to &quot;分镜二：开工&quot;">​</a></h3><ul><li>扫描结束，HUD 变成 <code>18 个光标 · N 层</code>，随即切到「游览中」。</li><li>光标散开，按「施工前沿」分配任务，页面从顶部开始一层层重建。</li></ul><h3 id="分镜三-建造" tabindex="-1">分镜三：建造 <a class="header-anchor" href="#分镜三-建造" aria-label="Permalink to &quot;分镜三：建造&quot;">​</a></h3><ul><li><strong>容器</strong>：十字光标飞到左上角 → 按住拖到右下角，拉出选框，四角白方块手柄 + 下方 <code>W × H</code> 徽章随拖拽实时变化 → 拉完先出现灰色占位 → 180~300ms 后真身交叉淡入。</li><li><strong>文字</strong>：I 形光标点进元素，逐字打出；新出现的字短暂带蓝色底，光标尾部有一根闪烁的插入符。</li><li><strong>图片</strong>：占位先出，随后 <code>clip-path</code> 自上而下揭开真图。</li><li><strong>导航 / 固定元素</strong>：单独一层，不随镜头滚动。</li></ul><h3 id="分镜四-复制-整套里最难的部分" tabindex="-1">分镜四：复制（整套里最难的部分） <a class="header-anchor" href="#分镜四-复制-整套里最难的部分" aria-label="Permalink to &quot;分镜四：复制（整套里最难的部分）&quot;">​</a></h3><ul><li>发现同构行（比如「推荐文章」列表的 <code>.group/item</code>），先留白。</li><li>母块完成后，<strong>复制光标</strong>飞到块内偏左上的位置（不是角上），按下、进入复制态。</li><li>拖拽体与光标 1:1 跟手，<strong>原位置红框 + 目标红框</strong>同时存在，两框之间实时显示间距读数。</li><li>松手后弹性落位（<code>cubic-bezier(.2,.9,.25,1.2)</code>，300ms），目标位置换成带手柄与 <code>W × H</code> 的选中框，停留 350ms 再淡出。</li><li>若副本里的文案和母块不同，会追加一次「双击全选 → 清空 → 重新逐字打出」。</li></ul><h3 id="分镜五-收尾" tabindex="-1">分镜五：收尾 <a class="header-anchor" href="#分镜五-收尾" aria-label="Permalink to &quot;分镜五：收尾&quot;">​</a></h3><ul><li>HUD 变成 <code>N 个光标 · X.Xs 完成 · 重播 · 关闭</code>。</li><li><code>viewY</code> 先平滑对齐真实页面能滚到的位置，再把真实滚动位置对齐，然后揭开覆盖层——避免两份页脚错位。</li><li>光标聚成蜂群在页面上方盘旋，可以跟真实鼠标互动；350ms 后覆盖层清空，页面滚回开播前的位置。</li></ul><hr><h2 id="四、实现架构" tabindex="-1">四、实现架构 <a class="header-anchor" href="#四、实现架构" aria-label="Permalink to &quot;四、实现架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>components/swarm/SwarmRebuild.vue</code></td><td>全流程编排：光标、任务调度、绘制、复制、镜头、HUD、收尾</td></tr><tr><td><code>components/swarm/capture.ts</code></td><td>扫描 DOM、建节点树、移植原版 <code>findGroups</code> 分组规则</td></tr><tr><td><code>components/swarm/sound.ts</code></td><td>程序化音源：钢琴泛音、噪声敲击、落位和弦</td></tr><tr><td><code>components/HomeContent.vue</code></td><td>两个触发口：点「开始」每次重播；滚走视频首屏自动接一次</td></tr></tbody></table><p>三个文件之外没有额外依赖，也不引入任何音频/图片素材。</p><hr><h2 id="五、关键技术细节" tabindex="-1">五、关键技术细节 <a class="header-anchor" href="#五、关键技术细节" aria-label="Permalink to &quot;五、关键技术细节&quot;">​</a></h2><h3 id="_5-1-光标-28×28-四种形态" tabindex="-1">5.1 光标：28×28，四种形态 <a class="header-anchor" href="#_5-1-光标-28×28-四种形态" aria-label="Permalink to &quot;5.1 光标：28×28，四种形态&quot;">​</a></h3><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-token-keyword);">const</span><span style="color:var(--shiki-token-constant);"> HOT</span><span style="color:var(--shiki-token-keyword);"> =</span><span style="color:var(--shiki-foreground);"> { arrow</span><span style="color:var(--shiki-token-keyword);">:</span><span style="color:var(--shiki-foreground);"> [</span><span style="color:var(--shiki-token-constant);">5</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-token-constant);"> 3.5</span><span style="color:var(--shiki-foreground);">]</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-foreground);"> dup</span><span style="color:var(--shiki-token-keyword);">:</span><span style="color:var(--shiki-foreground);"> [</span><span style="color:var(--shiki-token-constant);">5</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-token-constant);"> 3.5</span><span style="color:var(--shiki-foreground);">]</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-foreground);"> cross</span><span style="color:var(--shiki-token-keyword);">:</span><span style="color:var(--shiki-foreground);"> [</span><span style="color:var(--shiki-token-constant);">12</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-token-constant);"> 12</span><span style="color:var(--shiki-foreground);">]</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-foreground);"> ibeam</span><span style="color:var(--shiki-token-keyword);">:</span><span style="color:var(--shiki-foreground);"> [</span><span style="color:var(--shiki-token-constant);">12</span><span style="color:var(--shiki-token-punctuation);">,</span><span style="color:var(--shiki-token-constant);"> 12</span><span style="color:var(--shiki-foreground);">] }</span></span></code></pre></div><ul><li><code>arrow</code>：原版那支箭头路径，白色描边 + 品牌色填充。</li><li><code>dup</code>：白色阴影箭头 + 彩色箭头叠一起，表示「按住复制」。</li><li><code>cross</code>：先白 3.6px 再彩 1.5px 的双线十字——就是满屏看到的「＋」。</li><li><code>ibeam</code>：同样双线，打字时用。</li></ul><p>每帧只改一个 <code>transform</code>：<code>translate(-hx,-hy) rotate(angle) scale(1 - press*0.12)</code>；方向随速度旋转，速度低于 30px/s 不更新，空闲时角度向 0 衰减。</p><h3 id="_5-2-扫描与分组-照搬原版而不是「看着像」" tabindex="-1">5.2 扫描与分组：照搬原版而不是「看着像」 <a class="header-anchor" href="#_5-2-扫描与分组-照搬原版而不是「看着像」" aria-label="Permalink to &quot;5.2 扫描与分组：照搬原版而不是「看着像」&quot;">​</a></h3><p><code>capture.ts</code> 的常量就是验收线：</p><table tabindex="0"><thead><tr><th>常量</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>MAX_TEXT</code></td><td>260</td><td>单条文本最多取多长</td></tr><tr><td><code>MAX_ITEMS</code></td><td>420</td><td>最多产出多少条目，超量按深度裁剪</td></tr><tr><td><code>MIN_SIZE</code></td><td>2</td><td>小于 2px 不是元素</td></tr><tr><td><code>MIN_VISIBLE</code></td><td>3</td><td>完全不可见就跳过（含隐藏子树）</td></tr><tr><td><code>MAX_GROUP</code></td><td>48</td><td>一个组最多多少成员</td></tr></tbody></table><p>分组判定（<code>findGroups</code>）：</p><ul><li>子节点按签名分桶：<code>tagName + 归一化 className + fixed + 子树 kind 序列</code>。</li><li>桶内两两相近：高矮比 &lt; 1.8、宽窄比 &lt; 1.6。</li><li>排除「只有一段长文本（&gt;40 字）」和「子树条目 &lt; 2」的节点。</li><li><strong>成员 ≥ 2 即成组</strong>——这条是 <code>.group/item</code> 每屏两行能成组的关键，旧逻辑要求 ≥3 所以永远复制不到。</li><li>副本条目从任务集里摘除，只保留一个 dup 任务，依赖母块子树里的全部工单。</li></ul><h3 id="_5-3-三种任务" tabindex="-1">5.3 三种任务 <a class="header-anchor" href="#_5-3-三种任务" aria-label="Permalink to &quot;5.3 三种任务&quot;">​</a></h3><ul><li><code>boxTask</code>：拉框 + 占位 + 淡入。</li><li><code>textTask</code>：短文本直接点进去打；长文本先拉 ghost 框（4 手柄 + 徽章 + 两条测量线）再打。</li><li><code>dupTask</code>：抓取 → 复制态 → 跟手拖拽 → 落位 → 选中框 → 可选改字。</li></ul><p>调度按「施工前沿（frontier）」取任务，母块没完成的 dup 会被 <code>deps</code> 卡住；空闲光标会去做 <code>assistTask</code>（帮别人收尾）或 <code>roam</code>（随便晃）。</p><h3 id="_5-4-打字机" tabindex="-1">5.4 打字机 <a class="header-anchor" href="#_5-4-打字机" aria-label="Permalink to &quot;5.4 打字机&quot;">​</a></h3><ul><li>每个字 <code>12~40ms</code>；空格额外 <code>0~30ms</code>；换行 <code>+100ms</code>；2.5% 概率卡顿 <code>80~200ms</code>。</li><li>新字包进 <code>.sa</code>（<code>rgba(13,153,255,.28)</code>）短暂高亮。</li><li>插入符 1.5px 宽、<code>1.1em</code> 高、<code>steps(1)</code> 1s 闪烁。</li></ul><h3 id="_5-5-程序化声音" tabindex="-1">5.5 程序化声音 <a class="header-anchor" href="#_5-5-程序化声音" aria-label="Permalink to &quot;5.5 程序化声音&quot;">​</a></h3><p><code>SwarmSound</code> 用 <code>AudioContext</code> + 压缩器 + 混响总线，全部现场合成：</p><table tabindex="0"><thead><tr><th>方法</th><th>用在哪</th></tr></thead><tbody><tr><td><code>swell</code></td><td>开场扫描的低频涌动</td></tr><tr><td><code>arp</code></td><td>光标聚拢时的琶音</td></tr><tr><td><code>piano(midi, vel, pan)</code></td><td>落位/完成的正弦泛音（五声音阶，按面积定八度、按横坐标取音级）</td></tr><tr><td><code>clack</code> / <code>space</code></td><td>打字与空格的噪声敲击</td></tr><tr><td><code>press</code> / <code>snap</code></td><td>按下与吸附</td></tr><tr><td><code>place(area, x)</code></td><td>元素落位</td></tr><tr><td><code>dup(pan)</code></td><td>复制落位（带立体声偏移）</td></tr><tr><td><code>chord</code></td><td>全部完成的和弦</td></tr></tbody></table><p><code>ensure()</code> / <code>resume()</code> 在「开始」按钮的点击手势里调用——这也正是把触发口设计成按钮的原因：自动播放策略只认用户手势。</p><h3 id="_5-6-镜头与交接" tabindex="-1">5.6 镜头与交接 <a class="header-anchor" href="#_5-6-镜头与交接" aria-label="Permalink to &quot;5.6 镜头与交接&quot;">​</a></h3><ul><li>覆盖层有自己的滚动量 <code>viewY</code>，不依赖真实页面滚到底。</li><li>可走距离取 <code>max(真实可滚距离, 内容底部 − 视口 85%)</code>，页面不够长也能一路推下去。</li><li>收工前若 <code>viewY</code> 超过真实可滚距离，先 280ms 缓动对齐，再写真实 <code>scrollY</code>，最后才揭开覆盖层。</li><li>揭开 350ms 后清空覆盖层，并平滑滚回开播前的位置。</li></ul><h3 id="_5-7-hud-与交互" tabindex="-1">5.7 HUD 与交互 <a class="header-anchor" href="#_5-7-hud-与交互" aria-label="Permalink to &quot;5.7 HUD 与交互&quot;">​</a></h3><ul><li>覆盖层 <code>pointer-events: none</code>，只有 HUD 按钮可点；否则整页交互会被吃掉。</li><li>进度条按「已完成层数 / 总层数」推进。</li><li>Esc 退出，滚轮/触摸/方向键在播放期间被拦下。</li><li>静音开关直接 <code>setEnabled(false)</code>。</li></ul><hr><h2 id="六、踩过的坑" tabindex="-1">六、踩过的坑 <a class="header-anchor" href="#六、踩过的坑" aria-label="Permalink to &quot;六、踩过的坑&quot;">​</a></h2><ol><li><strong>扫描必须在隐藏页面之前</strong>。<code>walk</code> 会跳过 <code>visibility:hidden</code> 的子树，先加 <code>swarm-lock</code> 就什么都扫不到。</li><li><strong>两份页脚</strong>。覆盖层能滚得比真实页面更远，交接前不对齐就会同时看到两个页脚，像卡了一下。</li><li><strong>分组阈值</strong>。原逻辑要求 ≥3 个同构节点，<code>RecommendedCard</code> 的列表行只有两行，永远复制不到；改成 ≥2 才复刻出视频里的「留白 → 复制」。</li><li><strong>光标不是贴图</strong>。用一张静态箭头加文字名牌，和原版的多形态、热点、旋转、压缩放差得很远；最终全部改成 SVG 路径 + 每帧 transform。</li><li><strong>复制不是 tween</strong>。固定时长平移看起来像「飞过去」；改成按光标实际位置 <code>onStep</code> 同步偏移，才有 1:1 跟手的拖拽感。</li><li><strong>声音不能等页面加载完再建</strong>。<code>AudioContext</code> 必须在用户手势里 <code>ensure()</code> + <code>resume()</code>，否则被自动播放策略静音。</li><li><strong>降级要彻底</strong>。<code>prefers-reduced-motion</code> 下两个触发口都不启动，直接退回「下滑一屏」。</li></ol><hr><h2 id="七、验收清单" tabindex="-1">七、验收清单 <a class="header-anchor" href="#七、验收清单" aria-label="Permalink to &quot;七、验收清单&quot;">​</a></h2><ul><li>[x] 点「开始」→ 扫描 → 建造 → 游览 → 收尾，全流程可完整播完。</li><li>[x] 18 个光标从屏外聚拢，形态/热点/旋转/压缩放与原版一致。</li><li>[x] 每个块都有 <code>W × H</code> 徽章与四角手柄；文字逐字打出且带蓝色高亮。</li><li>[x] 同构行出现「留白 → 1:1 跟手复制 → 两红框 + 间距 → 弹性落位」。</li><li>[x] 声音全部为 Web Audio 合成，无外部音频文件。</li><li>[x] Esc 可中断；「开始」可反复重播；<code>prefers-reduced-motion</code> 自动降级。</li><li>[x] 收尾交接无跳变，清场后滚回原位；控制台零报错。</li></ul>',55))])}const f=a(p,[["render",h]]);export{_ as __pageData,f as default};
